private func bestReplacement(
    for member: PersistentStageMember,
    in candidates: [WindowSnapshot],
    claimed: Set<WindowID>
) -> WindowSnapshot? {
    var best: (window: WindowSnapshot, score: Double)?
    var second = Double.greatestFiniteMagnitude
    for candidate in candidates where !claimed.contains(candidate.id) {
        let score = frameDistance(member.frame, candidate.frame)
        if score < (best?.score ?? .greatestFiniteMagnitude) {
            second = best?.score ?? .greatestFiniteMagnitude
            best = (candidate, score)
        } else if score < second {
            second = score
        }
    }
    guard let best, best.score <= 360, second - best.score >= 120 else { return nil }
    return best.window
}

